function load_env_file(string $path): void { if(!is_file($path)) return; foreach(file($path, FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $line){$line=trim($line); if($line===''||str_starts_with($line,'#')||!str_contains($line,'='))continue; [$k,$v]=explode('=',$line,2);$k=trim($k);$v=trim($v);if($k===''||getenv($k)!==false)continue;if(strlen($v)>=2&&(($v[0]==='"'&&str_ends_with($v,'"'))||($v[0]==="'"&&str_ends_with($v,"'"))))$v=substr($v,1,-1);putenv($k.'='.$v);$_ENV[$k]=$v;}}
